-- ---------- 库存汇总（= 各商品有效批次剩余之和） ----------

-- ---------- 自检：库存汇总与批次合计必须一致 ----------
-- 若下面这条查询返回任何行，说明种子数据不自洽，请重新生成
SELECT s.product_id, s.quantity AS stock_qty, IFNULL(b.qty, 0) AS batch_qty
FROM stock s LEFT JOIN (
    SELECT product_id, SUM(stock_quantity) AS qty FROM stock_batch
    WHERE status = 1 GROUP BY product_id
) b ON b.product_id = s.product_id
WHERE s.quantity <> IFNULL(b.qty, 0);
